service {
  name = "web-service"
  id = "web-service-1"
  address = "10.0.1.10"
  port = 8080
  tags = ["primary", "v1.2.3", "production"]
  meta = {
    version = "1.2.3"
    environment = "production"
    team = "platform"
  }
  check {
    id = "web-service-health"
    name = "HTTP Health Check"
    http = "http://10.0.1.10:8080/health"
    interval = "10s"
    timeout = "3s"
    deregister_critical_service_after = "1m"
    tls_skip_verify = false
  }
  connect {
    sidecar_service {
      proxy {
        upstreams = [
          {
            destination_name = "database-service"
            local_bind_port = 9100
          },
          {
            destination_name = "cache-service"
            local_bind_port = 9200
          },
          {
            destination_name = "message-queue"
            local_bind_port = 9300
          }
        ]
        config {
          envoy_prometheus_bind_addr = "0.0.0.0:9102"
          envoy_tracing_json = jsonencode({
            tracing = {
              http = {
                name = "envoy.tracers.zipkin"
                config = {
                  collector_cluster = "jaeger_collector"
                  collector_endpoint = "/api/v2/spans"
                  trace_id_128bit = true
                  shared_span_context = false
                }
              }
            }
          })
        }
      }
    }
  }
}

Kind = "service-intentions"
Name = "web-service"
Sources = [
  {
    Name = "api-gateway"
    Action = "allow"
    Type = "http"
    Description = "Allow API gateway full access"
  },
  {
    Name = "mobile-app"
    Action = "allow"
    Permissions = [
      {
        Action = "read"
        HTTP {
          PathExact = "/api/users"
          Methods = ["GET"]
        }
      },
      {
        Action = "write"
        HTTP {
          PathPrefix = "/api/users"
          Methods = ["POST", "PUT"]
        }
      }
    ]
    Description = "Mobile app: read user list, create/update users"
  },
  {
    Name = "admin-service"
    Action = "allow"
    Permissions = [
      {
        Action = "write"
        HTTP {
          PathPrefix = "/admin"
          Methods = ["GET", "POST", "PUT", "DELETE"]
        }
      }
    ]
    Description = "Admin service: full admin access"
  },
  {
    Name = "*"
    Action = "deny"
    Description = "Deny all other services by default"
  }
]

Kind = "service-splitter"
Name = "frontend-service"
Splits = [
  {
    Weight = 90
    Service = "frontend-v1"
    ServiceSubset = "stable"
  },
  {
    Weight = 10
    Service = "frontend-canary"
    ServiceSubset = "canary"
  }
]
---
Kind = "service-router"
Name = "api-service"
Routes = [
  {
    Match {
      HTTP {
        PathPrefix = "/v2/"
      }
    }
    Destination {
      Service = "api-v2"
      PrefixRewrite = "/"
    }
  },
  {
    Match {
      HTTP {
        Header = [
          {
            Name = "x-version"
            Exact = "beta"
          }
        ]
      }
    }
    Destination {
      Service = "api-beta"
    }
  }
]
---
Kind = "service-resolver"
Name = "backend-service"
DefaultSubset = "v1"
Subsets = {
  "v1" = {
    Filter = "Service.Meta.version == v1"
  }
  "v2" = {
    Filter = "Service.Meta.version == v2"
  }
  "canary" = {
    Filter = "Service.Meta.version == canary"
  }
}

Kind = "ingress-gateway"
Name = "ingress-gateway"
TLS {
  TLSMinVersion = "TLSv1_2"
}
Listeners = [
  {
    Port = 8080
    Protocol = "http"
    Services = [
      {
        Name = "web-service"
        Hosts = ["web.example.com"]
      }
    ]
  },
  {
    Port = 8443
    Protocol = "https"
    TLS {
      Certificates = [
        {
          Kind = "secret"
          Name = "web-service-cert"
          Namespace = "default"
        }
      ]
    }
    Services = [
      {
        Name = "web-service"
        Hosts = ["web.example.com"]
      },
      {
        Name = "api-service"
        Hosts = ["api.example.com"]
      }
    ]
  }
]

Kind = "proxy-defaults"
Name = "global"
Config {
  protocol = "http"
  envoy_prometheus_bind_addr = "0.0.0.0:9102"
}
---
Kind = "mesh"
TransparentProxy {
  MeshDestinationsOnly = true
}

resource "consul_acl_policy" "service_mesh_policy" {
  name        = "service-mesh-policy"
  description = "Policy for service mesh operations"
  rules       = <<-RULE
    service_prefix "" {
      policy = "read"
    }
    service "consul" {
      policy = "write"
    }
    node_prefix "" {
      policy = "read"
    }
    agent_prefix "" {
      policy = "read"
    }
    session_prefix "" {
      policy = "read"
    }
    service_prefix "" {
      intentions = "read"
    }
    key_prefix "service-config/" {
      policy = "read"
    }
    key_prefix "service-health/" {
      policy = "write"
    }
  RULE
}

resource "consul_acl_token" "service_token" {
  description = "Token for service mesh applications"
  policies    = [consul_acl_policy.service_mesh_policy.name]
  local       = true
}

resource "vault_pki_secret_backend_role" "consul_intermediate" {
  backend          = vault_mount.pki_intermediate.path
  name             = "consul-intermediate"
  allowed_domains  = ["consul", "service.consul"]
  allow_subdomains = true
  max_ttl          = "720h"
  key_type         = "ec"
  key_bits         = 256
  server_flag      = true
  client_flag      = true
}

resource "consul_config_entry" "vault_ca" {
  kind = "ca-root"
  name = "vault-root-ca"
  config_json = jsonencode({
    Provider = "vault"
    Config = {
      address       = "https://vault.vault.svc.cluster.local:8200"
      token         = vault_token.consul_token.client_token
      root_cert_path = "pki-root/cert/ca"
      intermediate_cert_path = "pki-intermediate/cert/ca"
      private_key_path = "pki-intermediate/key/ca"
    }
  })
}

audit {
  enabled = true
  sink {
    type = "file"
    path = "/var/log/consul/audit.log"
    format = "json"
    rotate_duration = "24h"
    rotate_max_files = 30
    rotate_bytes = 1073741824
  }
}

Kind = "service-defaults"
Name = "web-service"
Protocol = "http"

EnvoyExtension:
  Name: "envoy.filters.http.fault"
  Required: true
  Type: "http-filter"
  Config: |
    {
      "delay": {
        "percentage": 1.0,
        "fixed_delay": "5s"
      },
      "abort": {
        "percentage": 0.5,
        "http_status": 503
      }
    }
